def drain(iterable):
    if getattr(iterable, 'popleft', False):
        def next_item(coll):
            return coll.popleft()
    elif getattr(iterable, 'popitem', False):
        def next_item(coll):
            return coll.popitem()
    else:
        def next_item(coll):
            return coll.pop()

    while True:
        try:
            yield next_item(iterable)
        except (IndexError, KeyError):
            raise StopIteration

