def get_ip_list(ip_network, mask=None):
	if mask and '/' not in ip_network:
		net = ipaddress.ip_network("{0}/{1}".format(ip_network, mask))
	elif '/' not in ip_network:
		return [str(ipaddress.ip_address(ip_network))]
	else:
