def parse_case_camel_to_snake(camel):
	# requirements = re
	return re.sub('((?<=[a-z0-9])[A-Z]|(?!^)[A-Z](?=[a-z]))', r'_\1', camel).lower()

def parse_case_snake_to_camel(snake, upper_first=True):
	snake = snake.split('_')
	first_part = snake[0]
	if upper_first:
