def difference (b, a):
    assert is_iterable(b)
    assert is_iterable(a)
    result = []
    for element in b:
        if not element in a:
            result.append (element)

    return result

def intersection (set1, set2):
    assert is_iterable(set1)
    assert is_iterable(set2)
    result = []
    for v in set1:
        if v in set2:
            result.append (v)
    return result

def contains (small, large):
    small = to_seq (small)
    large = to_seq (large)

    for s in small:
        if not s in large:
            return False
    return True

def equal (a, b):
    assert is_iterable(a)
    assert is_iterable(b)
    return contains (a, b) and contains (b, a)

