def wait_for_file_mtime_change(filename):
    try:
        mtime = os.stat(filename).st_mtime
        os.utime(filename, None)
        while mtime == os.stat(filename).st_mtime:
            time.sleep(1e-3)
            os.utime(filename, None)
    except OSError:
        pass

